tity", "type": "string"}, "path": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Path"}, "why": {"title": "Why", "type": "string"}}, "required": ["quantity", "why"], "title": "Missing", "type": "object"}, "Source": {"additionalProperties": false, "description": "Where a value stands: the file, and its page, table and depth when the file gives them.", "properties": {"file": {"title": "File", "type": "string"}, "page": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null, "title": "Page"}, "table": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Table"}, "depth": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Depth"}, "quote": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Quote"}}, "required": ["file"], "title": "Source", "type": "object"}}, "additionalProperties": false, "description": "What the geoscientist hands the case lead: proposals only, never a case it set.", "properties": {"values": {"items": {"$ref": "#/$defs/Finding"}, "title": "Values", "type": "array"}, "missing": {"items": {"$ref": "#/$defs/Missing"}, "title": "Missing", "type": "array"}, "disagreements": {"items": {"$ref": "#/$defs/Disagreement"}, "title": "Disagreements", "type": "array"}, "files_read": {"items": {"type": "string"}, "title": "Files Read", "type": "array"}}, "required": ["values", "missing", "disagreements", "files_read"], "title": "Findings", "type": "object"}

output.text:
## 6.7 Bounds

- cap: `max`; floor: `min`; a range with both ends: ONE requirement with both;
- exact: `min` = `max`;
- fraction, share, ratio, efficiency: no unit (70 % is `0.7`);
- days of operation: `over: duration`, `when: running`, unit `d`;
- number of units: `{on: doublet, quantity: count, min, max}`, no `over`, `when`, `unit`.

